async function exportReport(workspaceId){if(!workspaceId){toast.error('Choose a workspace with a completed scan first.');return}try{await downloadReportPdf(workspaceId);toast.success('PDF report generated and downloaded')}catch(error){toast.error(apiErrorMessage(error))}}
function downloadMockFile(filename,content){
  const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}))
  const link=document.createElement('a');link.href=url;link.download=filename;link.click()
  setTimeout(()=>URL.revokeObjectURL(url),1000)
  toast.success(filename.includes('report')?'Report generated and downloaded':'Export downloaded')
}
