 const loc=useLocation(),navigate=useNavigate(),{user,workspace:authWorkspace,workspaceId,logout}=useAuth(),inputRef=useRef(null),workspaceRef=useRef(null),bellRef=useRef(null),avatarRef=useRef(null),sidebarProfileRef=useRef(null),unread=notifications.filter(n=>!n.read).length,name=nav.find(x=>x[2]===loc.pathname)?.[0]||'Settings'
 useEffect(()=>{if(authWorkspace?.name)setWorkspace(authWorkspace.name)},[authWorkspace?.name])
 useEffect(()=>{let alive=true;Promise.all([fetchAll('/api/aws/resources',workspaceId),fetchAll('/api/aws/recommendations',workspaceId),fetchAll('/api/aws/history',workspaceId)]).then(([r,rec,h])=>alive&&setSearchData({resources:r,recommendations:rec,history:h})).catch(()=>alive&&setSearchData({resources:[],recommendations:[],history:[]}));return()=>{alive=false}},[workspaceId])
