  <div className="workspace-area" ref={workspaceRef}><button className="workspace" title={collapsed?workspace:undefined} aria-expanded={menu==='workspace'} onClick={()=>openMenu('workspace')}><i>{workspace.slice(0,1)}</i><span><b>{workspace}</b><small>{workspace==='CloudGuard Demo'?'Demo workspace':'Enterprise workspace'}</small></span>{switching?<LoaderCircle size={18} className="spin"/>:<motion.span animate={{rotate:menu==='workspace'?180:0}} transition={{duration:.2}}><ChevronDown size={18}/></motion.span>}</button><AnimatePresence>{menu==='workspace'&&<motion.div className="workspace-dropdown" initial={{opacity:0,y:-6,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-5,scale:.98}} transition={{duration:.16}}><div className="dropdown-heading"><b>Switch workspace</b><small>Choose an environment</small></div>{workspaces.map(w=><button key={w} disabled={Boolean(switching)} className={'workspace-option '+(workspace===w?'selected':'')} onClick={()=>switchWorkspace(w)}>{switching===w?<LoaderCircle size={16} className="spin"/>:<span className="workspace-option-icon">{w.slice(0,1)}</span>}<span>{w}{workspace===w&&<small>Current</small>}</span>{workspace===w&&<Check size={16}/>}</button>)}<div className="dropdown-separator"/><button className="workspace-action" onClick={()=>{setMenu('');setCreateOpen(true)}}><Plus size={16}/> Create Workspace</button><button className="workspace-action" onClick={()=>{setMenu('');toast.info('Workspace management opened');navigate('/settings')}}><MoreHorizontal size={16}/> Manage Workspaces</button><button className="workspace-action" onClick={goSettings}><Settings size={16}/> Settings</button></motion.div>}</AnimatePresence></div>
